SELECT 
FROM ai_business_application_version
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}
  AND del_flag = '0'
ORDER BY version_no DESC, id DESC

SELECT 
FROM ai_business_application_version
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}
  AND version_no = #{versionNo}
  AND del_flag = '0'
LIMIT 1

SELECT 
FROM ai_business_application_version
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}
  AND id = #{versionId}
  AND del_flag = '0'
LIMIT 1

SELECT COALESCE(MAX(version_no), 0)
FROM ai_business_application_version
WHERE tenant_id = #{tenantId}
  AND application_id = #{applicationId}
  AND del_flag = '0'
